    s1 = rng.sample(range(11), 2)
    s2 = rng.sample(range(11), 2)
    x1_val, y1_val = s1[0], s1[1]
    x2_val, y2_val = s2[0], s2[1]

    X1, Y1 = x1_val**2, y1_val**2
    X2, Y2 = x2_val**2, y2_val**2

